import { Bell, ChevronRight, Clock3, Mic, Package, Plus, ReceiptText, SlidersHorizontal, Tag } from 'lucide-react'
import type { ReactNode } from 'react'
import { NavLink } from 'react-router'
import { useTranslation } from 'react-i18next'
import { DemoImage } from '../components/DemoImage'
import { BatchPhoto } from '../components/BatchPhoto'
import { foodImage } from '../components/demo-images'
import { heldUnits } from './holds'
import type { VendorBatch, VendorFood, VendorStall, VendorWorkspace } from './model'
import { HawkerPredictionNudge } from '../clearance/PredictedClearance'
import { isTodayInMalaysia, LIKELY_CLEARANCE_THRESHOLD, vendorStallPrediction } from '../clearance/prediction'
import { MarketPulsePanel } from './MarketPulsePanel'
import './HawkerDashboard.css'

// `management` is the page's existing stall-management toolbar, placed at the foot of the right column
export function HawkerDashboard({workspace,stall,foods,batches,now,isDemo=false,onFood,onBatch,onStall,management}:{workspace:VendorWorkspace;stall:VendorStall;foods:VendorFood[];batches:VendorBatch[];now:Date;isDemo?:boolean;onFood:()=>void;onBatch:()=>void;onStall:(id:string)=>void;management?:ReactNode}) {
 const {i18n}=useTranslation()
 const text=(en:string,ms:string)=>i18n.language.startsWith('ms')?ms:en
 const active=batches.filter(b=>['active','needs-information'].includes(b.status)&&(!b.advisory_deadline||Date.parse(b.advisory_deadline)>now.getTime()))
 const latest=(food:VendorFood)=>batches.find(b=>b.food_item_id===food.id)
 const available=(b:VendorBatch)=>b.remaining_quantity===null?null:Math.max(0,b.remaining_quantity-heldUnits(workspace,b.id,now))
 const reminders=active.filter(b=>{const stock=available(b);return b.status==='needs-information'||stock!==null&&stock<=5||b.advisory_deadline&&Date.parse(b.advisory_deadline)-now.getTime()<=3600000})
 const label=(b:VendorBatch)=>b.status==='needs-information'?text('Add handling details','Tambah butiran pengendalian'):b.advisory_deadline&&Date.parse(b.advisory_deadline)-now.getTime()<=3600000?text(`${Math.max(0,Math.floor((Date.parse(b.advisory_deadline)-now.getTime())/60000))} min advisory left`,`${Math.max(0,Math.floor((Date.parse(b.advisory_deadline)-now.getTime())/60000))} min baki nasihat`):text('Low available stock','Stok tersedia rendah')
 const time=(value:string)=>new Date(value).toLocaleTimeString(i18n.language.startsWith('ms')?'ms-MY':'en-MY',{hour:'numeric',minute:'2-digit',timeZone:'Asia/Kuala_Lumpur'})
 const offers=workspace.freshness?.promotions.filter(p=>p.state==='active'&&Date.parse(p.ends)>now.getTime()&&active.some(b=>b.id===p.batch&&b.status==='active'&&b.advisory_deadline&&Date.parse(b.advisory_deadline)>now.getTime()))??[]
 const hasUnmarkedBatchToday=batches.some(b=>b.status==='active'&&b.advisory_deadline!==null&&Date.parse(b.advisory_deadline)>now.getTime()&&b.original_quantity!==null&&b.original_quantity>0&&isTodayInMalaysia(b.corrected_prepared_at??b.prepared_at,now)&&!offers.some(offer=>offer.batch===b.id))
 const clearancePrediction=isDemo?vendorStallPrediction(workspace,stall,now):null
 return <div className="hawker-overview">
  <div className="hawker-top"><label className="hawker-stall-choice">{text('Choose stall','Pilih gerai')}<select value={stall.id} onChange={event=>onStall(event.target.value)}>{workspace.stalls.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label></div>
  {/* Left column: stall summary, market pulse, products */}
  <div className="hawker-col hawker-col-main">
   <NavLink className="hawker-session" to="/hawker/accounting"><span className="hawker-session-icon"><ReceiptText size={18}/></span>{text("Session accounting & clearance decisions","Perakaunan sesi dan keputusan jualan lebihan")}<ChevronRight className="hawker-session-arrow" size={18}/></NavLink>
   <section className="hawker-card hawker-stall-card"><div className="hawker-welcome"><span className={`status-pill ${stall.open?'open':'closed'}`}><span className="status-dot"/>{text(stall.open?'Stall open':'Stall closed',stall.open?'Gerai dibuka':'Gerai ditutup')}</span><span className="eyebrow">{text('YOUR STALL, AT A GLANCE','GERAI ANDA SEKILAS PANDANG')}</span><h1>{stall.name}</h1></div>
    <div className="hawker-stats"><div><span className="hawker-stat-icon"><Tag size={20}/></span><strong>{offers.length}</strong><span>{text('Current offers','Tawaran semasa')}</span></div><div><span className="hawker-stat-icon"><Bell size={20}/></span><strong>{reminders.length}</strong><span>{text('Batches to review','Kelompok untuk semakan')}</span></div><div><span className="hawker-stat-icon"><Package size={20}/></span><strong>{active.length}</strong><span>{text('Current batches','Kelompok semasa')}</span></div></div>
    <p className="hawker-stall-caption">{text('A little less admin. More time for good food.','Kurangkan kerja pentadbiran. Lebih masa untuk makanan enak.')}</p></section>
   {isDemo&&<MarketPulsePanel stall={stall}/>}
   <section className="hawker-card dashboard-section hawker-products"><div className="dashboard-product-grid"><div className="hawker-products-head"><span className="hawker-products-icon" aria-hidden="true"><Package size={20}/></span><h2>{text('Your products','Produk anda')}</h2><NavLink to="/hawker/stall">{text('Manage menu','Urus menu')}<ChevronRight size={17}/></NavLink></div>{foods.slice(0,6).map(f=>{const b=latest(f);return <NavLink className="dashboard-product" to="/hawker/stall#batches" key={f.id}><DemoImage image={foodImage(f.name)} description={f.name}/><div className="product-copy"><h3>{f.name}</h3><strong>RM {(f.price_sen/100).toFixed(2)}</strong><span><Clock3 size={14}/>{b?`${text('Batch','Kelompok')} #${b.batch_number} · ${time(b.prepared_at)}`:text('No batch yet','Belum ada kelompok')}</span></div></NavLink>})}</div>{!foods.length&&<div className="dashboard-empty"><p>{text('Add your first dish to start a batch.','Tambah hidangan pertama untuk memulakan kelompok.')}</p><button className="button primary" onClick={onFood}><Plus size={18}/>{text('Add food','Tambah makanan')}</button></div>}</section>
  </div>
  {/* Right column: review queue, next-batch actions, clearance, stall management */}
  <div className="hawker-col hawker-col-side">
   <section className="hawker-card dashboard-section hawker-attention"><div className="section-heading"><h2><Bell size={26}/>{text('Needs your attention','Perlu perhatian anda')}</h2><NavLink to="/hawker/promotions">{text('View alerts','Lihat peringatan')}<ChevronRight size={17}/></NavLink></div><p className="section-caption">{text('Advisory windows, not a food-safety guarantee. Review each batch before offering it.','Tempoh nasihat, bukan jaminan keselamatan makanan. Semak setiap kelompok sebelum ditawarkan.')}</p>{clearancePrediction&&clearancePrediction.score>=LIKELY_CLEARANCE_THRESHOLD&&(hasUnmarkedBatchToday||clearancePrediction.isSample)&&<HawkerPredictionNudge prediction={clearancePrediction} locale={i18n.language}/>}<div className="attention-grid">{reminders.slice(0,3).map(b=>{const food=foods.find(f=>f.id===b.food_item_id);return <NavLink className="dashboard-product attention-card" to="/hawker/promotions" key={b.id}><div className="product-image"><BatchPhoto food={food?.name??'Food'} number={b.batch_number} foodId={b.food_item_id} batchId={b.id} photo={b.photo}/><span className="attention-label"><Clock3 size={13}/>{label(b)}</span></div><div className="product-copy"><h3>{food?.name}</h3><span>{text('Batch','Kelompok')} #{b.batch_number} · {time(b.prepared_at)}</span></div></NavLink>})}</div>{reminders.length>0&&<NavLink className="button primary hawker-see-more" to="/hawker/stall#batches">{text('See more','Lihat lagi')}</NavLink>}{!reminders.length&&<div className="dashboard-empty hawker-notice"><Bell size={18}/><p>{text('No batches need immediate review. Keep batch details up to date.','Tiada kelompok memerlukan semakan segera. Pastikan butiran kelompok terkini.')}</p></div>}</section>
   <aside className="hawker-card hawker-quick"><span className="hawker-quick-icon"><Mic size={24}/></span><h2>{text('Ready for the next batch?','Sedia untuk kelompok seterusnya?')}</h2><p>{text('Speak the details, review the draft, then confirm. You always have the final say.','Sebut butiran, semak draf, kemudian sahkan. Keputusan akhir di tangan anda.')}</p><NavLink className="button primary" to="/hawker/voice"><Mic size={20}/>{text('List by voice','Senaraikan dengan suara')}</NavLink><button className="button secondary" onClick={onFood}><Plus size={19}/>{text('Add food','Tambah makanan')}</button><button className="button secondary" onClick={onBatch}><Package size={19}/>{text('New batch','Kelompok baharu')}</button><hr className="hawker-quick-rule"/><NavLink to="/hawker/stall#batches" className="quick-link">{text('View batch audit trail','Lihat jejak audit kelompok')}<ChevronRight size={16}/></NavLink><p className="small">{text('Every batch keeps its preparation photo and original timestamps in the audit trail.','Setiap kelompok menyimpan foto penyediaan dan masa asal dalam jejak audit.')}</p></aside>
   <section className="hawker-card dashboard-section hawker-clearance"><div className="section-heading"><h2><Tag size={22}/>{text('Clearance & promotions','Jualan penghabisan & promosi')}</h2><NavLink to="/hawker/promotions">{text('Manage offers','Urus tawaran')}<ChevronRight size={17}/></NavLink></div>{offers.slice(0,2).map(p=>{const batch=batches.find(b=>b.id===p.batch),food=foods.find(f=>f.id===batch?.food_item_id);return <NavLink className="dashboard-offer" key={p.id} to="/hawker/promotions">{batch?<BatchPhoto food={food?.name??'Food'} number={batch.batch_number} foodId={batch.food_item_id} batchId={batch.id} photo={batch.photo}/>:<DemoImage image={foodImage(food?.name??'')} description={food?.name??'Food'}/> }<div><span className="eyebrow">{text('HAWKER-CONFIRMED OFFER','TAWARAN DISAHKAN PENJAJA')}</span><h3>{p.title}</h3><strong>RM {(p.price/100).toFixed(2)}</strong><p><Clock3 size={15}/>{text('Ends','Tamat')} {time(p.ends)}</p></div></NavLink>})}{!offers.length&&<div className="dashboard-empty hawker-clearance-empty"><p>{text('No current offers. Review an eligible batch to prepare a clearance listing.','Tiada tawaran semasa. Semak kelompok yang layak untuk menyediakan tawaran.')}</p><NavLink className="button secondary" to="/hawker/promotions"><SlidersHorizontal size={17}/>{text('Review eligible batches','Semak kelompok layak')}</NavLink></div>}</section>
   {management}
  </div>
 <details className="hawker-fab"><summary aria-label={text('Open stall quick actions','Buka tindakan pantas gerai')}><Plus size={28}/></summary><div><button onClick={event=>{event.currentTarget.closest('details')?.removeAttribute('open');onFood()}}><Plus size={18}/>{text('Add food','Tambah makanan')}</button><button onClick={event=>{event.currentTarget.closest('details')?.removeAttribute('open');onBatch()}}><Package size={18}/>{text('New batch','Kelompok baharu')}</button><NavLink to="/hawker/voice"><Mic size={18}/>{text('List by voice','Senaraikan dengan suara')}</NavLink></div></details>
 </div>
}
